//! Minimal GPUI hello world, written against the gpui contract.
//!
//! The code never names a fork: `gpui` is bound to the provider chosen in
//! Cargo.toml via a dependency rename. Swap providers with:
//!
//!     cargo gocar add gpui-ce
//!     cargo gocar lock
//!
//! then `cargo build --locked`.

use gpui::*;

struct HelloWorld;

impl Render for HelloWorld {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .flex()
            .size_full()
            .bg(rgb(0x101418))
            .justify_center()
            .items_center()
            .child(
                div()
                    .text_xl()
                    .text_color(rgb(0xffffff))
                    .child("Hello from gocar!"),
            )
    }
}

fn main() {
    Application::new().run(|cx: &mut App| {
        cx.open_window(WindowOptions::default(), |_, cx| cx.new(|_cx| HelloWorld))
            .unwrap();
    });
}

//! Minimal GPUI hello world against the gpui contract, post-split launch
//! shape: `gpui` (the renamed fork) provides the API, the per-fork platform
//! companion provides `application()`. The code never names a fork — swap
//! providers with:
//!
//!     cargo gocar add gpui-ce
//!     cargo gocar lock
//!
//! then `cargo build --locked`.

use gpui::{
    App, Bounds, Context, IntoElement, Render, SharedString, Window, WindowBounds,
    WindowOptions, div, prelude::*, px, rgb, size,
};
use gpui_platform::application;

struct HelloWorld {
    text: SharedString,
}

impl Render for HelloWorld {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .flex()
            .size_full()
            .bg(rgb(0x101418))
            .justify_center()
            .items_center()
            .child(
                div()
                    .text_xl()
                    .text_color(rgb(0xffffff))
                    .child(format!("Hello from {}!", self.text)),
            )
    }
}

fn main() {
    application().run(|cx: &mut App| {
        let bounds = Bounds::centered(None, size(px(480.), px(320.)), cx);
        cx.open_window(
            WindowOptions {
                window_bounds: Some(WindowBounds::Windowed(bounds)),
                ..Default::default()
            },
            |_, cx| cx.new(|_| HelloWorld { text: "gocar".into() }),
        )
        .unwrap();
        cx.activate(true);
    });
}

